/**
 * The `type/subtype` portion of the header value, or `undefined` when the
 * header is missing or does not describe a valid media type. Returning
 * `undefined` avoids handing out the meaningless `/` placeholder.
 * @returns {string | undefined}
 */
get mediaType () {
  if (this.#valid === false) return undefined
  return `${this.#type}/${this.#subtype}`
}
